import { GAME_DATA as DATA } from './sobreviva-data.js';

const state = { step:0, monthlyBudget:0, selectedExpenses:new Map(), totalExpenses:0, remainingBalance:0, healthChoice:'', healthSimulationCost:970, protectionScore:0, playerProfile:'', healthBudgetRange:'', age:'', city:'', peopleCount:'', contractType:'', hasCompany:'', copayPreference:'', leadData:{name:'',email:'',phone:''} };
const root = document.querySelector('#game');
const currency = new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const money = n => currency.format(n);
const analytics = (event, properties={}) => { window.dataLayer = window.dataLayer || []; window.dataLayer.push({event,...properties}); console.info('[Legatto analytics]',event,properties); };
function calculateMonthlyExpenses(){ return [...state.selectedExpenses.values()].reduce((sum,item)=>sum + item.value,0); }
function calculateRemainingBalance(){ return state.monthlyBudget - state.totalExpenses; }
function calculateHealthImpact(){ return calculateRemainingBalance() - state.healthSimulationCost; }
function calculateProtectionScore(){ const discretionary = state.totalExpenses / Math.max(state.monthlyBudget,1); const reserve = Math.max(calculateRemainingBalance(),0) / Math.max(state.monthlyBudget,1); return Math.max(12,Math.min(94,Math.round(42 + reserve*42 - discretionary*18 + (state.healthChoice==='plano'?14:0)))); }
function calculateProfile(){ if(state.protectionScore>=76) return ['Prevenido','Você criou espaço no orçamento antes de precisar dele.']; if(state.protectionScore>=55) return ['Equilibrista','Seu mês funciona bem enquanto tudo acontece conforme o esperado.']; if(state.totalExpenses>state.monthlyBudget*.72) return ['Espontâneo','Seu orçamento privilegia o presente e deixa pouco espaço para desvios.']; return ['Planejador','Você está olhando para o seu mês com atenção e margem para ajustar.']; }
function header(){ const percent = Math.min(100,Math.max(0,(state.step/13)*100)); return `<div class="topbar"><a class="brand" href="index.html">Legatto</a><div class="progress"><span>${state.step?`${String(state.step).padStart(2,'0')} / 13`:''}</span><div class="progress-track"><span style="width:${percent}%"></span></div></div></div>`; }
function shell(content, disclaimer=true){ root.innerHTML=`<section class="screen">${header()}<div class="content">${content}</div>${disclaimer?'<p class="disclaimer">Esta experiência possui finalidade educativa e comercial. Valores apresentados são exemplos ilustrativos e não representam preços garantidos de consultas, exames ou planos.</p>':''}</section>`; attach(); }
function intro(){ state.step=0; shell(`<p class="eyebrow">Uma experiência Legatto</p><h1 class="title">Seu dinheiro<br />sobreviveria a um <em>imprevisto?</em></h1><p class="lede">Monte seu mês e descubra em menos de 1 minuto como pequenas decisões podem mudar o seu espaço para o inesperado.</p><div class="actions"><button class="button" data-next>Começar o desafio <span>↘</span></button></div><p class="caption">Leva menos de 1 minuto. Sem cadastro agora.</p>`,false); }
function budget(){ state.step=1; shell(`<p class="eyebrow">Seu ponto de partida</p><h1 class="title">Quanto você costuma ter disponível por mês?</h1><p class="lede">Pense apenas nos gastos pessoais e cotidianos. É uma simulação, não uma análise financeira.</p><div class="choice-grid">${[500,1000,1500,2000,3000].map(n=>`<button class="choice" data-budget="${n}"><strong>${money(n)}</strong><small>${n===3000?'ou mais':'disponíveis'}</small></button>`).join('')}<label class="choice"><strong>Outro valor</strong><input class="field" aria-label="Valor personalizado" inputmode="numeric" placeholder="R$" data-custom /></label></div><div class="actions"><button class="button" data-next disabled>Continuar</button></div>`); }
function expenses(){ state.step=2; state.totalExpenses=calculateMonthlyExpenses(); state.remainingBalance=calculateRemainingBalance(); shell(`<div class="expense-layout"><div><p class="eyebrow">Monte seu mês</p><h1 class="title">Pequenos gastos também contam.</h1><p class="lede">Selecione o que costuma fazer parte da sua rotina. Você pode mudar de ideia a qualquer momento.</p><div class="expense-list">${DATA.expenses.map(([id,label,value])=>`<label class="expense ${state.selectedExpenses.has(id)?'active':''}"><input type="checkbox" data-expense="${id}" ${state.selectedExpenses.has(id)?'checked':''}/><b>${label}</b><span>${money(state.selectedExpenses.get(id)?.value ?? value)}/mês</span></label>`).join('')}</div></div><aside class="meter"><p>Seu orçamento</p><strong class="money">${money(state.monthlyBudget)}</strong><div class="bar"><span style="width:${Math.min(100,state.totalExpenses/state.monthlyBudget*100)}%"></span></div><div class="mini"><span>Gastos escolhidos</span><b>${money(state.totalExpenses)}</b></div><div class="mini"><span>Restante</span><b class="${state.remainingBalance<0?'negative':''}">${money(state.remainingBalance)}</b></div><div class="actions"><button class="button" data-next>Ver meu mês</button></div></aside></div>`); }
function timeline(){ state.step=3; analytics('timeline_started'); const items=DATA.timeline.map(([day,label,value],i)=>`<div class="event" style="animation-delay:${i*.15}s"><time>${day}</time><div><b>${label}</b><p>-${money(value)}</p></div></div>`).join(''); shell(`<p class="eyebrow">Seu mês começou</p><h1 class="title">Até aqui,<br />tudo sob controle.</h1><div class="timeline">${items}</div><div class="actions"><button class="button" data-next>Continuar <span>→</span></button></div>`); }
function healthEvent(){ state.step=4; analytics('health_event_viewed'); shell(`<div class="interrupt"><p class="day">DIA 19</p><h1 class="title">Isso não estava<br />no orçamento.</h1><p class="lede">Você acordou com uma dor forte e precisa procurar atendimento.</p><div class="actions"><button class="button" data-next>O que eu faria? <span>→</span></button></div></div>`); }
function decision(){ state.step=5; shell(`<p class="eyebrow">Escolha uma reação</p><h1 class="title">O que você faria?</h1><div class="decision-grid"><button class="decision" data-choice="particular"><strong>Pagar particular</strong><small>Usar o orçamento disponível para atendimento.</small></button><button class="decision" data-choice="reserva"><strong>Usar minha reserva</strong><small>Recorrer ao valor separado para imprevistos.</small></button><button class="decision" data-choice="adiar"><strong>Adiar e esperar</strong><small>Postergar uma decisão de cuidado.</small></button><button class="decision" data-choice="plano"><strong>Tenho plano de saúde</strong><small>Usar uma cobertura já planejada.</small></button></div><p class="notice">Sintomas importantes devem ser avaliados por profissionais de saúde. Esta escolha é apenas uma simulação financeira e não é recomendação médica.</p>`); }
function impact(){ state.step=6; const before=calculateRemainingBalance(), after=state.healthChoice==='plano'?before:calculateHealthImpact(); shell(`<p class="eyebrow">Simulação ilustrativa</p><h1 class="title">Seu saldo mudou.</h1><p class="lede">Para visualizar o impacto, usamos um exemplo de atendimento particular.</p><div class="impact"><div><p>Consulta</p><strong>${money(DATA.healthCost.consulta)}</strong></div><div><p>Exames</p><strong>${money(DATA.healthCost.exames)}</strong></div><div><p>Imagem</p><strong>${money(DATA.healthCost.imagem)}</strong></div></div><p class="notice">Valores meramente ilustrativos. Custos reais variam conforme estabelecimento, região, procedimento e situação clínica.</p><div class="compare"><div class="compare-card"><p>Você tinha</p><strong>${money(before)}</strong></div><div class="compare-card highlight"><p>Saldo após o imprevisto</p><strong>${money(after)}</strong></div></div><div class="actions"><button class="button" data-next>Agora compare <span>→</span></button></div>`); }
function comparison(){ state.step=7; shell(`<p class="eyebrow">Planejamento</p><h1 class="title">Alguns gastos são previsíveis.<br /><em>Outros não.</em></h1><div class="compare"><div class="compare-card"><p>Seus gastos mensais selecionados</p><strong>${money(state.totalExpenses)}</strong><p>Delivery, rotina, lazer e escolhas do mês.</p></div><div class="compare-card highlight"><p>Exemplo de orçamento destinado à saúde</p><strong>${money(300)}</strong><p>Não é preço de plano. É uma referência de planejamento.</p></div></div><p class="notice">Existem planos e modalidades em diferentes faixas de preço. O valor real depende de idade, região, cobertura, acomodação, coparticipação e contratação.</p><div class="actions"><button class="button" data-next>Ver meu índice <span>→</span></button></div>`); }
function score(){ state.step=8; state.protectionScore=calculateProtectionScore(); [state.playerProfile,state.profileText]=calculateProfile(); shell(`<p class="eyebrow">Seu Índice de Proteção</p><h1 class="title">Uma leitura lúdica do seu mês.</h1><div class="score-wrap"><div class="score-ring"><div><strong>${state.protectionScore}</strong><span>/ 100</span></div></div><div><h2 class="title" style="font-size:44px">${state.playerProfile}</h2><p class="lede">${state.profileText}</p><p class="notice">Este índice não é diagnóstico financeiro nem recomendação profissional. Ele é uma forma simples de enxergar o impacto de escolhas e imprevistos.</p></div></div><div class="actions"><button class="button" data-next>Incluir saúde no plano <span>→</span></button></div>`); }
function healthBudget(){ state.step=9; shell(`<p class="eyebrow">Próximo passo</p><h1 class="title">E se saúde já estivesse no planejamento?</h1><p class="lede">Quanto você consideraria investir por mês em saúde?</p><div class="choice-grid">${DATA.ranges.map(range=>`<button class="choice ${state.healthBudgetRange===range?'selected':''}" data-range="${range}"><strong>${range}</strong><small>Faixa de investimento</small></button>`).join('')}</div><div class="actions"><button class="button" data-next disabled>Encontrar opções</button></div>`); }
function qualify(){ state.step=10; shell(`<p class="eyebrow">Seu contexto</p><h1 class="title">Vamos entender o que faz sentido.</h1><p class="lede">Informações rápidas para organizar uma conversa posterior. Não pedimos documentos nesta etapa.</p><div class="form-grid"><label><span>Idade</span><input class="field" inputmode="numeric" data-field="age" value="${state.age}" /></label><label><span>Cidade</span><input class="field" data-field="city" value="${state.city}" /></label><label><span>Para quem seria o plano?</span><select class="field" data-field="peopleCount"><option value="">Selecione</option><option>Individual</option><option>Casal</option><option>Família</option><option>Empresa</option></select></label><label><span>Possui CNPJ ou MEI?</span><select class="field" data-field="hasCompany"><option value="">Selecione</option><option>Sim</option><option>Não</option></select></label><label class="wide"><span>Preferência</span><select class="field" data-field="copayPreference"><option value="">Selecione</option><option>Mensalidade menor com coparticipação</option><option>Mensalidade maior com menos coparticipação</option><option>Ainda não sei</option></select></label></div><div class="actions"><button class="button" data-next>Continuar <span>→</span></button></div>`); document.querySelector('[data-field="peopleCount"]').value=state.peopleCount; document.querySelector('[data-field="hasCompany"]').value=state.hasCompany; document.querySelector('[data-field="copayPreference"]').value=state.copayPreference; }
function lead(){ state.step=11; analytics('lead_started'); shell(`<p class="eyebrow">Seu perfil está pronto</p><h1 class="title">Para ver opções, como podemos falar com você?</h1><p class="lede">Você escolhe se quer seguir a conversa. Seus dados serão usados apenas para este contato.</p><form class="form-grid" id="lead-form"><label class="wide"><span>Nome</span><input class="field" required data-lead="name" /></label><label><span>WhatsApp</span><input class="field" required inputmode="tel" data-lead="phone" /></label><label><span>E-mail</span><input class="field" required type="email" data-lead="email" /></label></form><label class="consent"><input type="checkbox" data-consent /> <span>Autorizo o contato da Legatto sobre opções de saúde. Li e concordo com a política de privacidade.</span></label><p class="error" data-error></p><div class="actions"><button class="button" data-submit>Ver opções de planos <span>→</span></button></div>`); }
function result(){ state.step=13; analytics('result_viewed',{profile:state.playerProfile}); shell(`<p class="eyebrow">Seu resultado</p><h1 class="title">Vamos encontrar opções compatíveis com seu perfil.</h1><p class="lede">Uma conversa com a Legatto pode organizar as alternativas sem prometer valores ou coberturas antes da cotação.</p><div class="compare"><div class="compare-card"><p>Faixa de investimento</p><strong>${state.healthBudgetRange}</strong></div><div class="compare-card"><p>Seu perfil</p><strong>${state.playerProfile}</strong></div></div><div class="actions"><a class="button" href="https://wa.me/5511971371823?text=${encodeURIComponent('Olá, concluí o desafio Sobreviva ao Mês e quero falar sobre opções de saúde.') }" target="_blank" rel="noopener" data-whatsapp>Falar com um especialista <span>↗</span></a><button class="button ghost" data-restart>Refazer simulação</button></div><button class="share" data-share>Compartilhar meu resultado ↗</button>`); }
const screens=[intro,budget,expenses,timeline,healthEvent,decision,impact,comparison,score,healthBudget,qualify,lead,result];
function render(){ screens[state.step](); }
function next(){ state.step=Math.min(state.step+1,screens.length-1); render(); }
function attach(){ document.querySelector('[data-next]')?.addEventListener('click',next); document.querySelectorAll('[data-budget]').forEach(btn=>btn.addEventListener('click',()=>{ state.monthlyBudget=Number(btn.dataset.budget); document.querySelectorAll('[data-budget]').forEach(x=>x.classList.remove('selected')); btn.classList.add('selected'); document.querySelector('[data-next]').disabled=false; analytics('budget_selected',{value:state.monthlyBudget}); })); document.querySelector('[data-custom]')?.addEventListener('input',e=>{state.monthlyBudget=Number(e.target.value.replace(/\D/g,''));document.querySelector('[data-next]').disabled=!state.monthlyBudget}); document.querySelectorAll('[data-expense]').forEach(input=>input.addEventListener('change',()=>{const source=DATA.expenses.find(x=>x[0]===input.dataset.expense); if(input.checked) state.selectedExpenses.set(source[0],{label:source[1],value:source[2]}); else state.selectedExpenses.delete(input.dataset.expense); analytics('expense_selected',{expense:input.dataset.expense,selected:input.checked}); expenses();})); document.querySelectorAll('[data-choice]').forEach(btn=>btn.addEventListener('click',()=>{state.healthChoice=btn.dataset.choice;analytics('health_choice_selected',{choice:state.healthChoice});next()})); document.querySelectorAll('[data-range]').forEach(btn=>btn.addEventListener('click',()=>{state.healthBudgetRange=btn.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');document.querySelector('[data-next]').disabled=false;analytics('health_budget_selected',{range:state.healthBudgetRange})})); document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('change',()=>state[el.dataset.field]=el.value)); document.querySelector('[data-submit]')?.addEventListener('click',submitLead); document.querySelector('[data-restart]')?.addEventListener('click',()=>{Object.assign(state,{step:0,monthlyBudget:0,selectedExpenses:new Map(),totalExpenses:0,remainingBalance:0,healthChoice:'',protectionScore:0,playerProfile:'',healthBudgetRange:''});analytics('game_restarted');render()}); document.querySelector('[data-share]')?.addEventListener('click',share); document.querySelector('[data-whatsapp]')?.addEventListener('click',()=>analytics('whatsapp_clicked',{source:'game_result'})); }
async function submitLead(){ const error=document.querySelector('[data-error]'), consent=document.querySelector('[data-consent]').checked; document.querySelectorAll('[data-lead]').forEach(el=>state.leadData[el.dataset.lead]=el.value.trim()); if(!state.leadData.name||!state.leadData.phone||!state.leadData.email||!consent){error.textContent='Preencha os dados e confirme a autorização de contato para continuar.';return;} const payload={...state.leadData,age:state.age,city:state.city,peopleCount:state.peopleCount,contractType:state.contractType,hasCompany:state.hasCompany,copayPreference:state.copayPreference,healthBudgetRange:state.healthBudgetRange,protectionScore:state.protectionScore,playerProfile:state.playerProfile,monthlyBudget:state.monthlyBudget,monthlyExpenses:state.totalExpenses}; analytics('lead_submitted',{profile:state.playerProfile}); try{const response=await fetch('/api/leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}); if(!response.ok) throw new Error('Lead API unavailable');}catch{ /* Static build: result remains usable; production API can replace this endpoint without UI changes. */ } state.step=12; result(); }
async function share(){ const text=`Meu perfil no desafio Sobreviva ao Mês foi: ${state.playerProfile}. Faça o seu.`; analytics('result_shared',{profile:state.playerProfile}); if(navigator.share) await navigator.share({title:'Sobreviva ao Mês | Legatto',text,url:location.href}); else await navigator.clipboard?.writeText(`${text} ${location.href}`); }
analytics('game_started'); render();
